<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{listPublicArticles,type PublicArticleSummary}from'../../api/articles';import{listPublicNavigations,type PublicNavigation}from'../../api/navigation';import{listPublicSiteConfig}from'../../api/siteConfig';import PublicSiteHeader from'../../components/PublicSiteHeader.vue';import PublicSiteFooter from'../../components/PublicSiteFooter.vue';import{setPageMeta}from'../../seo';const items=ref<PublicNavigation[]>([]),articles=ref<PublicArticleSummary[]>([]),serviceLinks=ref<Array<{name:string;url:string}>>([]),loading=ref(true),error=ref('');setPageMeta({description:'吉林省高等学校毕业生就业信息网，提供就业资讯、政策法规、业务指南和公共服务入口。'});const serviceItems=computed(()=>items.value.filter(i=>i.position==='SERVICE'));const siteGroups=computed(()=>{const m=new Map<string,PublicNavigation[]>();items.value.filter(i=>i.position==='SITE').forEach(i=>{const k=i.category||'网站导航';m.set(k,[...(m.get(k)||[]),i])});return Array.from(m,([name,links])=>({name,links}))});const articleGroups=computed(()=>{const m=new Map<number,{columnId:number;columnAlias:string;columnName:string;articles:PublicArticleSummary[]}>();articles.value.forEach(a=>{const g=m.get(a.columnId)||{columnId:a.columnId,columnAlias:a.columnAlias,columnName:a.columnName,articles:[]};g.articles.push(a);m.set(a.columnId,g)});return Array.from(m.values())});onMounted(async()=>{try{const[n,a,c]=await Promise.all([listPublicNavigations(),listPublicArticles(null,0,30),listPublicSiteConfig()]);items.value=n;articles.value=a.items;const raw=c.find(i=>i.key==='SERVICE_LINKS')?.value||'[]';serviceLinks.value=JSON.parse(raw)}catch(e){error.value=e instanceof Error?e.message:'公开内容加载失败'}finally{loading.value=false}})
</script>
<template><PublicSiteHeader/><main class="home-main"><section class="home-banner"><div class="site-width banner-inner"><div><p>吉林省高等学校毕业生就业信息网</p><h1>就业信息与公共服务</h1><span>服务高校毕业生就业创业，连接政策、学校与用人单位。</span></div></div></section><p v-if="loading" class="public-state">正在加载公开内容…</p><p v-else-if="error" class="public-state error-text">{{error}}</p><section class="site-width home-two-column" data-testid="public-content"><div class="home-panel notice-panel"><header><h2>通知公告</h2><router-link to="/column/notice">更多 &gt;</router-link></header><ul><li v-for="a in articles.slice(0,6)" :key="a.id"><router-link :data-testid="`public-article-${a.id}`" :to="`/article/${a.id}`">{{a.title}}</router-link><time v-if="a.publishDate">{{a.publishDate}}</time></li><li v-if="!articles.length" class="empty-item">暂无已发布内容</li></ul></div><aside class="service-panel"><h2>公共服务</h2><div class="service-shortcuts"><a v-for="l in serviceLinks" :key="l.name" :href="l.url" :target="l.url.startsWith('http')?'_blank':undefined" rel="noopener noreferrer">{{l.name}}</a><template v-for="i in serviceItems" :key="i.id"><a v-if="i.external" :href="i.href" :target="i.newWindow?'_blank':undefined" rel="noopener noreferrer">{{i.name}}</a><router-link v-else :to="i.href">{{i.name}}</router-link></template></div></aside></section><section class="site-width home-section"><header class="section-title"><h2>就业资讯</h2></header><div class="news-columns"><section v-for="g in articleGroups.slice(0,4)" :key="g.columnId" class="news-column"><header><h3>{{g.columnName}}</h3><router-link :to="g.columnAlias?`/column/${g.columnAlias}`:`/columns/${g.columnId}`">更多</router-link></header><ul><li v-for="a in g.articles.slice(0,6)" :key="a.id"><router-link :to="`/article/${a.id}`">{{a.title}}</router-link><time v-if="a.publishDate">{{a.publishDate}}</time></li></ul></section></div></section><section class="site-width guide-strip"><router-link to="/page/guide/jypq">就业派遣</router-link><router-link to="/page/guide/dagl">档案管理</router-link><router-link to="/page/guide/dygl">流动党员</router-link><router-link to="/page/guide/xlrz">学历认证</router-link><router-link to="/page/guide/contact">联系我们</router-link><router-link to="/page/guide/faq">常见问题</router-link></section><section class="site-width external-grid"><div class="external-placeholder"><h2>最新招聘</h2><p>慧就业招聘内容区域，本轮保留页面结构，后续接入实际 iframe。</p><router-link to="/page/jobs/positions">进入招聘信息</router-link></div><div class="external-placeholder"><h2>直播课程</h2><p>外部直播课程内容区域，本轮保留入口与占位。</p><router-link to="/page/live-course">进入直播课程</router-link></div></section><section v-if="siteGroups.length" class="site-width home-section site-navigation"><header class="section-title"><h2>网站导航</h2></header><div v-for="g in siteGroups" :key="g.name" class="site-link-group"><strong>{{g.name}}</strong><div><template v-for="i in g.links" :key="i.id"><a v-if="i.external" :href="i.href" :target="i.newWindow?'_blank':undefined" rel="noopener noreferrer">{{i.name}}</a><router-link v-else :to="i.href">{{i.name}}</router-link></template></div></div></section></main><PublicSiteFooter/></template>
